void unlock_pagevec(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i, unlocked = 0;
    struct page *backup[PAGEVEC_SIZE];
    int backup_count = 0;

    /* Phase 1: Isolate pages to be unlocked and prepare backup vector */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            /* Adjust the count of unlocked pages */
            unlocked++;
            continue;
        } else {
            /* Add to backup for later processing */
            backup[backup_count++] = page;
        }
    }

    /* Adjust pvec to contain only pages that are not being unlocked */
    for (i = 0; i < backup_count; i++) {
        pvec->pages[i] = backup[i];
    }
    pvec->nr_pages = backup_count;

    /* Phase 2: Unlock pages and handle reference correctly */
    for (i = 0; i < unlocked; i++) {
        page = pvec->pages[i];
        if (page->count == 1) {
            /* Special handling for last reference to avoid deadlock */
            unlock_page(page);
        } else {
            unlock_page(page);
        }
    }

    /* Phase 3: Process pages for fast path putback */
    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        putback_page(zone, page);
    }
}

