void pagevec_unrelease(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;
    int nr_unlocked = 0;

    /* Phase 1: Isolate pages to be unlocked and prepare for fast path */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            nr_unlocked++;
            continue;
        }
        /* Move pages not being unlocked to a backup vector */
        if (nr_unlocked < pagevec_count(pvec)) {
            pvec->pages[nr_unlocked++] = page;
        }
    }

    /* Phase 2: Unlock pages and manage state */
    for (i = 0; i < nr_unlocked; i++) {
        page = pvec->pages[i];
        unlock_page(page);
        if (page_ref_count(page) == 1) {
            /* Handle last reference to avoid deadlocks */
            pagevec_put_page(zone, page);
        }
    }

    /* Phase 3: Process fast path putback pages */
    for (i = nr_unlocked; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        pagevec_put_page(zone, page);
    }

    /* Update page vector count to reflect the number of pages in backup */
    pagevec_reinit(pvec);
}

void pagevec_release(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i, unlock_count = 0;
    struct pagevec backup_pvec;

    pagevec_init(&backup_pvec, 0);

    /* Phase 1: isolate pages that are locked and prepare for unlock */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_count++;
        } else {
            pagevec_add(&backup_pvec, page);
        }
    }

    /* Adjust the pagevec to only include pages that are locked */
    pvec->nr = unlock_count;

    /* Phase 2: unlock the pages */
    for (i = 0; i < unlock_count; i++) {
        page = pvec->pages[i];
        unlock_page(page);
        if (page->_count == 1)
            put_page(page); /* Ensure proper handling of last reference */
    }

    /* Phase 3: put back pages that are not being unlocked using fast path */
    pagevec_putback(&backup_pvec, zone);
}
